```{=html}
<style>
/* Imagen normal en escritorio */
#profile-pic {
  border-radius: 10px;
}

/* Mobile circle background image */
#mobile-image-bg {
    display: none;
}

/* Estilo general desktop */
#intro-container {
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: relative;
}

/* Ajustes para pantallas pequeñas */
@media (max-width: 768px) {
    #intro-container {
        flex-direction: row;
        align-items: center;
        text-align: left;
    }

    #text-container {
        width: 100% !important;
        z-index: 2;
        text-align: left;
    }

    #image-container {
        display: none; /* Oculta imagen normal */
    }

    #mobile-image-bg {
        display: block;
        position: absolute;
        right: 5%;
        top: 22%;
        width: 180px;
        height: 180px;
        background-image: url('images/foto.png');
        background-size: cover;
        background-position: right;
        border-radius: 50%;
        z-index: 1;
        opacity: 0.85;
    }

    #profile-pic {
        display: none;
    }
}
</style>
